window.NORTHCREST_DEPARTMENTS = [{"slug": "cardiology", "name": "Cardiology", "short": "Heart care", "icon": "heart", "categories": ["medical", "diagnostics-emergency"], "tagline": "Heart checks, cath lab and cardiac rehab under one roof.", "summary": "Complete heart care from ECG and echo to angioplasty, pacemakers and structured cardiac rehabilitation.", "image": "dept-cardiology", "imageAlt": "A cardiologist reading an ECG trace with a patient", "consultants": 9, "opd": "Mon to Sat, 8:00 to 20:00", "floor": "Block A, Level 2", "detail": true, "page": "department-cardiology.html", "hero": "hero-cardiology", "heroAlt": "A cardiology team reviewing a heart scan on a monitor", "overview": "The Northcrest Heart Institute brings interventional cardiologists, cardiac surgeons, imaging specialists and rehab physiotherapists into one team. A 24/7 cath lab and a dedicated cardiac ICU mean a heart attack patient can go from the emergency door to an open artery in under 60 minutes.", "facts": [["Cath lab", "24/7, 2 suites"], ["Door-to-balloon", "Under 60 min"], ["Cardiac ICU", "18 beds"], ["Consultants", "9"]], "conditions": ["Chest pain and heart attack", "Coronary artery disease", "High blood pressure", "Heart failure", "Irregular heartbeat (arrhythmia)", "Valve disease", "Congenital heart defects in adults", "High cholesterol"], "procedures": [["Coronary angiography and angioplasty", "Radial-access stenting with same-day discharge for most planned cases."], ["Pacemaker and ICD implantation", "Device clinics follow you for life with remote monitoring."], ["Echocardiography and stress testing", "2D/3D echo, TMT and stress echo reported the same day."], ["Cardiac rehabilitation", "A 12-week supervised exercise and lifestyle programme after a heart event."]], "technology": [["Bi-plane cath lab", "Lower radiation and sharper images for complex procedures."], ["3D echocardiography", "Detailed valve and chamber views without an invasive test."], ["Holter and event monitors", "24-hour to 14-day rhythm recording at home."]], "faqs": [["Do I need a referral to see a cardiologist?", "No. You can book directly online or at the OPD desk. Bring any previous ECGs, reports and your current medicines."], ["What should I do if I have chest pain?", "Call our emergency line +91 80 4718 1000 or 108 immediately. Do not drive yourself. Chew a 300 mg aspirin if you are not allergic and a doctor has not told you otherwise."], ["How long is the stay after an angioplasty?", "Most planned angioplasties through the wrist go home the same evening or the next morning. Emergency cases usually stay 2 to 3 days."], ["Is cardiac rehab covered by insurance?", "Many policies cover the supervised sessions. Our TPA desk checks your cover before you start."]]}, {"slug": "neurology", "name": "Neurology & Neurosurgery", "short": "Brain and spine", "icon": "brain", "categories": ["medical", "surgical"], "tagline": "Stroke-ready care for the brain, spine and nerves.", "summary": "Stroke, epilepsy, headache, movement disorders and spine surgery with a round-the-clock stroke team.", "image": "dept-neurology", "imageAlt": "A neurologist examining a brain MRI scan", "consultants": 7, "opd": "Mon to Sat, 9:00 to 18:00", "floor": "Block B, Level 3", "detail": true, "page": "department-neurology.html", "hero": "hero-neurology", "heroAlt": "Doctors reviewing brain scans on a large screen", "overview": "Our neurosciences team treats conditions of the brain, spinal cord and nerves, from first seizures and migraines to strokes and complex spine surgery. A stroke code activates the emergency team, CT scanner and neurologist the moment a patient arrives.", "facts": [["Stroke code", "24/7"], ["Neuro ICU", "12 beds"], ["EEG lab", "Video EEG"], ["Consultants", "7"]], "conditions": ["Stroke and mini-stroke (TIA)", "Epilepsy and seizures", "Migraine and chronic headache", "Parkinson's disease", "Multiple sclerosis", "Neuropathy and nerve pain", "Slipped disc and sciatica", "Brain and spinal tumours"], "procedures": [["Clot-busting treatment and thrombectomy", "Time-critical stroke treatment with a target of under 45 minutes door-to-needle."], ["Minimally invasive spine surgery", "Keyhole disc and decompression surgery with faster recovery."], ["Video EEG monitoring", "Records seizures on video and brain activity together to guide treatment."], ["Botox for migraine and spasticity", "Day-care injections for chronic migraine and muscle stiffness."]], "technology": [["3 Tesla MRI", "High-resolution brain and spine imaging."], ["Neuro-navigation", "GPS-style guidance for precise brain and spine surgery."], ["Nerve conduction lab", "EMG and NCS studies reported in 48 hours."]], "faqs": [["What are the warning signs of a stroke?", "Remember BE FAST: Balance loss, Eyes (vision loss), Face drooping, Arm weakness, Speech difficulty, Time to call 108 or our emergency line."], ["Do I need an MRI before my first visit?", "No. The neurologist will examine you first and order only the tests you need."], ["Is spine surgery always necessary for a slipped disc?", "Most people improve with medicines and physiotherapy. Surgery is advised only when there is nerve weakness or pain that does not settle."], ["Can I drive with epilepsy?", "Rules depend on how well seizures are controlled. Your neurologist will advise you and provide a fitness letter when it is safe."]]}, {"slug": "orthopaedics", "name": "Orthopaedics", "short": "Bones and joints", "icon": "bone", "categories": ["surgical"], "tagline": "Joint replacement, sports injury and trauma care.", "summary": "Knee and hip replacement, arthroscopy, fracture care and physiotherapy to get you moving again.", "image": "dept-orthopaedics", "imageAlt": "An orthopaedic surgeon reviewing a knee X-ray", "consultants": 8, "opd": "Mon to Sat, 9:00 to 19:00", "floor": "Block C, Level 1", "detail": true, "page": "department-orthopaedics.html", "hero": "hero-orthopaedics", "heroAlt": "A physiotherapist helping a patient exercise their knee", "overview": "From a sprained ankle to a full knee replacement, our orthopaedic surgeons and physiotherapists plan your care around one goal: getting you back to the activities you enjoy. Most joint replacement patients walk with support on the day after surgery.", "facts": [["Joint replacements", "1,200+ a year"], ["Walking after surgery", "Day 1"], ["Physio gym", "On site"], ["Consultants", "8"]], "conditions": ["Knee and hip arthritis", "Fractures and trauma", "Sports injuries and ligament tears", "Shoulder pain and frozen shoulder", "Back and neck pain", "Osteoporosis", "Carpal tunnel syndrome", "Children's bone problems"], "procedures": [["Total knee and hip replacement", "Muscle-sparing techniques and an enhanced recovery pathway."], ["Arthroscopy (keyhole surgery)", "ACL reconstruction, meniscus repair and shoulder stabilisation."], ["Fracture fixation", "24/7 trauma theatre for broken bones and complex injuries."], ["Physiotherapy and rehab", "One-to-one sessions in our physio gym, plus a home exercise plan."]], "technology": [["Computer-navigated knee surgery", "Precise implant alignment for longer-lasting joints."], ["Digital X-ray and DEXA", "Low-dose imaging and bone-density scans."], ["Laminar-flow theatres", "Ultra-clean air to lower infection risk in joint surgery."]], "faqs": [["How long does a knee replacement last?", "Modern implants last 20 years or more for most people. Staying active and keeping a healthy weight helps them last longer."], ["How soon can I walk after joint replacement?", "Most patients stand and walk with a frame on the day after surgery and go home in 3 to 4 days."], ["Do I need surgery for a ligament tear?", "Not always. Partial tears often heal with bracing and physiotherapy. Your surgeon will discuss your activity level and goals."], ["Is physiotherapy included in the surgery package?", "In-hospital physiotherapy is included. Outpatient sessions after discharge are billed separately or as a discounted bundle."]]}, {"slug": "oncology", "name": "Oncology", "short": "Cancer care", "icon": "ribbon", "categories": ["medical", "surgical"], "tagline": "Medical, surgical and radiation oncology with one tumour board.", "summary": "Cancer screening, chemotherapy, surgery and radiotherapy planned together by a weekly tumour board.", "image": "dept-oncology", "imageAlt": "A patient receiving care in a calm oncology day-care unit", "consultants": 6, "opd": "Mon to Sat, 9:00 to 17:00", "floor": "Block D, Level 2", "detail": true, "page": "department-oncology.html", "hero": "hero-oncology", "heroAlt": "An oncology nurse talking with a patient in the day-care unit", "overview": "Every new cancer diagnosis at Northcrest is reviewed by a tumour board of medical, surgical and radiation oncologists, pathologists and radiologists. You get one written plan, one nurse navigator and a day-care unit designed for comfort during long treatments.", "facts": [["Tumour board", "Weekly"], ["Day-care chairs", "24"], ["Nurse navigator", "For every patient"], ["Consultants", "6"]], "conditions": ["Breast cancer", "Lung cancer", "Head and neck cancers", "Colorectal and stomach cancers", "Blood cancers (leukaemia, lymphoma)", "Prostate and kidney cancers", "Gynaecological cancers", "Cancer screening for high-risk families"], "procedures": [["Chemotherapy and immunotherapy", "Given in a calm day-care unit with oncology-trained nurses."], ["Cancer surgery", "Organ-preserving and minimally invasive operations where possible."], ["Radiation therapy", "Image-guided treatment planned to protect healthy tissue."], ["Supportive and palliative care", "Pain control, nutrition and counselling from day one."]], "technology": [["Linear accelerator (IGRT)", "Image-guided radiotherapy with millimetre accuracy."], ["PET-CT", "Whole-body scans to stage cancer and check response."], ["Closed-system chemo pharmacy", "Safe, sterile preparation of every dose."]], "faqs": [["What is a tumour board?", "A weekly meeting where specialists review your scans and biopsy together and agree one plan. You and your family then discuss it with your lead oncologist."], ["Can I get a second opinion?", "Yes. Bring your reports and biopsy slides; our team usually reviews them within 5 working days."], ["Will I lose my hair during chemotherapy?", "It depends on the medicines. Your oncologist will tell you before you start and our nurses can arrange scalp cooling where suitable."], ["Is cancer treatment covered by insurance?", "Most health policies cover chemotherapy, radiotherapy and surgery. Our TPA desk handles pre-authorisation for you."]]}, {"slug": "paediatrics", "name": "Paediatrics & Neonatology", "short": "Child health", "icon": "child", "categories": ["women-children"], "tagline": "Child-friendly care from newborns to teenagers.", "summary": "Well-baby clinics, vaccinations, a level III NICU and paediatric specialists for every stage of childhood.", "image": "dept-paediatrics", "imageAlt": "A paediatrician gently examining a smiling child", "consultants": 8, "opd": "Mon to Sun, 8:00 to 21:00", "floor": "Block E, Level 1", "detail": true, "page": "department-paediatrics.html", "hero": "hero-paediatrics", "heroAlt": "A paediatrician listening to a young child's heartbeat", "overview": "Our children's wing has its own entrance, play areas and paediatric emergency room. Paediatricians, neonatologists and child specialists care for everything from routine vaccines to premature babies in our level III neonatal intensive care unit.", "facts": [["NICU", "Level III, 20 cots"], ["Paediatric ER", "24/7"], ["Vaccination clinic", "Daily"], ["Consultants", "8"]], "conditions": ["Fever, cough and common infections", "Asthma and allergies", "Premature and low birth-weight babies", "Newborn jaundice", "Growth and nutrition concerns", "Childhood diabetes", "Developmental delay", "Stomach problems in children"], "procedures": [["Vaccinations and well-baby checks", "Full national and optional vaccine schedules with growth tracking."], ["Neonatal intensive care", "Ventilation, phototherapy and kangaroo care for newborns who need extra help."], ["Paediatric emergency care", "Children are seen by paediatric doctors, not adult teams."], ["Child development clinic", "Speech, occupational therapy and early intervention."]], "technology": [["Level III NICU", "Advanced ventilators and incubators with 1:1 nursing for the sickest babies."], ["Paediatric-sized equipment", "Scopes, cannulas and monitors made for children."], ["Transport incubator", "Safe transfer of newborns from other hospitals."]], "faqs": [["Do you follow the national vaccination schedule?", "Yes. We follow the IAP schedule and also offer optional vaccines. Bring your child's vaccination card to every visit."], ["Can parents stay with their child?", "One parent can stay with a child at all times on the ward and in the NICU we encourage kangaroo care."], ["When should I bring my child to the emergency room?", "Come straight away for breathing difficulty, a fit, a very drowsy child, a high fever in a baby under 3 months or signs of dehydration."], ["Do you have weekend clinics?", "Yes. The paediatric OPD is open every day including Sundays and public holidays."]]}, {"slug": "gynaecology", "name": "Obstetrics & Gynaecology", "short": "Women's health", "icon": "female", "categories": ["women-children", "surgical"], "tagline": "Pregnancy, birth and women's health at every age.", "summary": "Antenatal care, high-risk pregnancy, natural and caesarean birth, fertility support and keyhole gynaecological surgery.", "image": "dept-gynaecology", "imageAlt": "An obstetrician performing a pregnancy ultrasound", "consultants": 7, "opd": "Mon to Sat, 9:00 to 19:00", "floor": "Block E, Level 2", "detail": true, "page": "department-gynaecology.html", "hero": "hero-gynaecology", "heroAlt": "An obstetrician talking with an expectant mother", "overview": "Our women's health team supports you from your first period problems to pregnancy, birth and menopause. Private birthing suites, a 24/7 obstetric theatre and our neonatal unit next door give you and your baby every safety net.", "facts": [["Births a year", "3,000+"], ["Birthing suites", "8 private"], ["Obstetric theatre", "24/7"], ["Consultants", "7"]], "conditions": ["Routine and high-risk pregnancy", "Period problems and PCOS", "Fibroids and ovarian cysts", "Endometriosis", "Infertility", "Menopause symptoms", "Urinary leakage and prolapse", "Cervical cancer screening"], "procedures": [["Antenatal care packages", "Scans, tests and doctor visits through all three trimesters."], ["Normal and caesarean delivery", "Private suites with epidural pain relief available 24/7."], ["Laparoscopic gynaecological surgery", "Keyhole removal of fibroids, cysts and hysterectomy."], ["Fertility evaluation and IUI", "Step-by-step fertility work-up and treatment."]], "technology": [["4D ultrasound", "Detailed anomaly and growth scans."], ["Central fetal monitoring", "Every labour room is watched from the nurses' station."], ["Hysteroscopy suite", "Day-care diagnosis and treatment inside the womb."]], "faqs": [["When should I book my first pregnancy visit?", "As soon as you have a positive test, ideally before 8 weeks. Your first visit includes a dating scan and blood tests."], ["Can my partner be present at the birth?", "Yes. One birth partner can stay with you in the birthing suite, including for a planned caesarean in most cases."], ["Do you offer painless delivery?", "Yes. Epidural pain relief is available 24/7 from our obstetric anaesthetists."], ["Is a Pap smear painful?", "It may feel slightly uncomfortable but it is quick and not usually painful. It is recommended every 3 years from age 25."]]}, {"slug": "gastroenterology", "name": "Gastroenterology", "short": "Digestive health", "icon": "stomach", "categories": ["medical", "surgical"], "tagline": "Endoscopy, liver care and GI surgery.", "summary": "Acidity, liver disease, IBS and endoscopy with a dedicated GI surgery team.", "image": "dept-gastro", "imageAlt": "A gastroenterologist explaining a digestive health plan to a patient", "consultants": 6, "opd": "Mon to Sat, 9:00 to 18:00", "floor": "Block B, Level 1", "detail": false, "page": "departments.html#dept-gastroenterology"}, {"slug": "pulmonology", "name": "Pulmonology", "short": "Lungs and breathing", "icon": "lungs", "categories": ["medical"], "tagline": "Asthma, COPD, sleep studies and lung function tests.", "summary": "Breathing problems, chronic cough, sleep apnoea and TB care with a full lung function lab.", "image": "dept-pulmonology", "imageAlt": "A doctor reviewing a chest X-ray on a lightbox", "consultants": 5, "opd": "Mon to Sat, 9:00 to 17:00", "floor": "Block B, Level 2", "detail": false, "page": "departments.html#dept-pulmonology"}, {"slug": "nephrology", "name": "Nephrology & Urology", "short": "Kidney care", "icon": "kidney", "categories": ["medical", "surgical"], "tagline": "Kidney disease, dialysis, stones and transplant.", "summary": "Chronic kidney disease clinics, a 20-bed dialysis unit, stone treatment and kidney transplant.", "image": "dept-nephrology", "imageAlt": "A patient resting during kidney dialysis treatment", "consultants": 6, "opd": "Mon to Sat, 8:00 to 18:00", "floor": "Block A, Level 3", "detail": false, "page": "departments.html#dept-nephrology"}, {"slug": "ent", "name": "ENT", "short": "Ear, nose and throat", "icon": "ear", "categories": ["surgical"], "tagline": "Hearing, sinus, voice and sleep surgery.", "summary": "Hearing tests, sinus and tonsil surgery, cochlear implants and voice clinics for all ages.", "image": "dept-ent", "imageAlt": "An ENT specialist examining a patient's ear", "consultants": 4, "opd": "Mon to Sat, 9:00 to 17:00", "floor": "Block C, Level 2", "detail": false, "page": "departments.html#dept-ent"}, {"slug": "dermatology", "name": "Dermatology", "short": "Skin, hair and nails", "icon": "skin", "categories": ["medical"], "tagline": "Medical and cosmetic skin care.", "summary": "Acne, eczema, psoriasis, hair loss and mole checks, plus laser and cosmetic dermatology.", "image": "dept-dermatology", "imageAlt": "A dermatologist checking a patient's skin", "consultants": 4, "opd": "Mon to Sat, 10:00 to 19:00", "floor": "Block C, Level 2", "detail": false, "page": "departments.html#dept-dermatology"}, {"slug": "emergency", "name": "Emergency & Trauma", "short": "24/7 emergency", "icon": "ambulance", "categories": ["diagnostics-emergency"], "tagline": "Level 1 trauma centre and ambulance network, 24/7.", "summary": "A 30-bed emergency department, trauma theatre and advanced life-support ambulances, always open.", "image": "dept-emergency", "imageAlt": "An ambulance team bringing a patient into the emergency department", "consultants": 12, "opd": "Open 24/7, 365 days", "floor": "Ground floor, Block A", "detail": false, "page": "departments.html#dept-emergency"}];
